return ['project-id-version'=>'Expiring Posts 2.0.0','report-msgid-bugs-to'=>'https://wordpress.org/support/plugin/expiring-posts','po-revision-date'=>'2026-11-26T17:30:31+00:00','last-translator'=>'Ivan Kruchkoff','language-team'=>'Thai','language'=>'th','mime-version'=>'1.0','content-type'=>'text/plain; charset=UTF-8','content-transfer-encoding'=>'8bit','plural-forms'=>'nplurals=1; plural=0;','x-domain'=>'expiring-posts','x-generator'=>'Expiring Posts build.py','messages'=>['%1$s %2$s, %3$s at %4$s:%5$s'=>'%2$s %1$s %3$s เวลา %4$s:%5$s','%1$s-%2$s'=>'%1$s-%2$s','An expiry date is required.'=>'ต้องระบุวันหมดอายุ','Automatically move a post to an "Expired" status on a date you choose. Works with the block editor and the classic editor.'=>'ย้ายโพสต์ไปยังสถานะ "หมดอายุ" โดยอัตโนมัติในวันที่คุณเลือก ใช้งานได้ทั้งในตัวแก้ไขบล็อกและตัวแก้ไขแบบคลาสสิก','Cancel'=>'ยกเลิก','Change expiry: %s'=>'เปลี่ยนการหมดอายุ: %s','Close'=>'ปิด','Day'=>'วัน','Edit'=>'แก้ไข','Edit expiry date and time'=>'แก้ไขวันและเวลาหมดอายุ','Either the post or expiration date provided are not valid.'=>'โพสต์หรือวันหมดอายุที่ระบุไม่ถูกต้อง','Expire now'=>'ให้หมดอายุทันที','Expire this post'=>'ตั้งให้โพสต์นี้หมดอายุ','Expired'=>'หมดอายุ','Expired <span class="count">(%s)</span>'=>'หมดอายุ <span class="count">(%s)</span>','Expired on: %s'=>'หมดอายุเมื่อ: %s','Expires'=>'หมดอายุ','Expires on: %s'=>'หมดอายุวันที่: %s','Expires: %s'=>'หมดอายุ: %s','Expiring Posts'=>'โพสต์หมดอายุ','Expiry'=>'การหมดอายุ','Expiry date and time'=>'วันและเวลาหมดอายุ','Expiry date in the site timezone. Dates with a UTC offset are converted.'=>'วันหมดอายุตามเขตเวลาของเว็บไซต์ วันที่ที่มีค่าชดเชย UTC จะถูกแปลง','Hour'=>'ชั่วโมง','Invalid expiry date.'=>'วันหมดอายุไม่ถูกต้อง','Minute'=>'นาที','Month'=>'เดือน','Never'=>'ไม่มีกำหนด','Never expire'=>'ไม่มีวันหมดอายุ','OK'=>'ตกลง','On this date the post moves to the Expired status and is hidden from visitors.'=>'ในวันนี้ โพสต์จะถูกย้ายไปยังสถานะ "หมดอายุ" และถูกซ่อนจากผู้เยี่ยมชม','Post expiry settings.'=>'การตั้งค่าการหมดอายุของโพสต์','Save Post'=>'บันทึกโพสต์','Sorry, you are not allowed to change the expiry of this post.'=>'ขออภัย คุณไม่ได้รับอนุญาตให้เปลี่ยนการหมดอายุของโพสต์นี้','The post provided is not a valid post.'=>'โพสต์ที่ระบุไม่ใช่โพสต์ที่ถูกต้อง','The post provided is not valid.'=>'โพสต์ที่ระบุไม่ถูกต้อง','This date has passed. The post will expire shortly after you save.'=>'วันที่นี้ผ่านไปแล้ว โพสต์จะหมดอายุหลังจากบันทึกไม่นาน','This is not a valid post.'=>'นี่ไม่ใช่โพสต์ที่ถูกต้อง','This post cannot be expired, the expiration date is invalid.'=>'ไม่สามารถทำให้โพสต์นี้หมดอายุได้ วันหมดอายุไม่ถูกต้อง','This post has expired and is hidden from visitors. Publish it again to restore it.'=>'โพสต์นี้หมดอายุแล้วและถูกซ่อนจากผู้เยี่ยมชม เผยแพร่อีกครั้งเพื่อกู้คืน','This post has expired. Publish it again to make it visible.'=>'โพสต์นี้หมดอายุแล้ว เผยแพร่อีกครั้งเพื่อให้มองเห็นได้','Whether the post expires on the given date.'=>'โพสต์จะหมดอายุในวันที่ระบุหรือไม่','Year'=>'ปี','post statusExpired'=>'หมดอายุ']];
